    private static string Id()=>Guid.NewGuid().ToString("N");
    private static byte[] Document()=>Encoding.UTF8.GetBytes("%PDF-1.7\nSynthetic private SQL attachment.\n%%EOF\n");
    private static MultipartFormDataContent Form(string version,string caption="متن نمونهٔ همراه پیوست",byte[]? bytes=null,string filename="مدرک نمونه.pdf"){
        bytes??=Document();var form=new MultipartFormDataContent();form.Add(new StringContent(version),"version");form.Add(new StringContent(caption),"body");form.Add(new StringContent("fa"),"locale");form.Add(new StringContent(PrivateFileRules.Hash(bytes)),"sha256");var file=new ByteArrayContent(bytes);file.Headers.ContentType=new("application/pdf");form.Add(file,"file",filename);return form;
    }
    private WebApplicationFactory<Program> Factory(PrivateFileSqlTests.Store store,PrivateFileSqlTests.Scan scanner,DownloadWriteGate? gate=null)=>sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(s=>{s.RemoveAll<IPrivateFileStore>();s.AddSingleton<IPrivateFileStore>(store);s.RemoveAll<IPrivateFileScanner>();s.AddSingleton<IPrivateFileScanner>(scanner);if(gate is not null)s.AddSingleton<IStartupFilter>(gate);}));
    private async Task<(HttpClient Client,string Owner)> Customer(WebApplicationFactory<Program> factory){await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="filecustomer"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true};Assert.True((await users.CreateAsync(user,sql.Password)).Succeeded);var session=await scope.ServiceProvider.GetRequiredService<AuthService>().PasswordAsync(new(name,sql.Password),true,true,false,default);var client=factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Authorization=new("Bearer",session.AccessToken);client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");return(client,user.Id);}
    private async Task<HttpClient> Staff(WebApplicationFactory<Program> factory,string role="SupportAgent"){
        await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="filestaff"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,RequireMfa=true};Assert.True((await users.CreateAsync(user,sql.Password)).Succeeded);Assert.True((await users.AddToRoleAsync(user,role)).Succeeded);var client=factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3173");client.DefaultRequestHeaders.Add("X-Sayman-Client","admin");client.DefaultRequestHeaders.Add("X-Sayman-Admin","1");var pending=await Json(await client.PostAsJsonAsync("/api/auth/password",new{Identifier=name,Password=sql.Password}));client.DefaultRequestHeaders.Authorization=new("Bearer",pending["accessToken"]!.GetValue<string>());using(var forbidden=await client.PostAsync("/api/admin/support/tickets/"+Id()+"/attachments/"+Id(),new StringContent("not parsed")))Assert.Equal(HttpStatusCode.Forbidden,forbidden.StatusCode);var setup=await Json(await client.PostAsJsonAsync("/api/auth/mfa/setup",new{}));client.DefaultRequestHeaders.Authorization=new("Bearer",setup["accessToken"]!.GetValue<string>());var signed=await Json(await client.PostAsJsonAsync("/api/auth/mfa/verify",new{Code=Totp.Code(setup["secret"]!.GetValue<string>(),DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30)}));client.DefaultRequestHeaders.Authorization=new("Bearer",signed["accessToken"]!.GetValue<string>());return client;
    }
    private static async Task<JsonNode> Json(HttpResponseMessage response,string? capture=null){using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"Unexpected HTTP {(int)response.StatusCode}: {raw}");if(capture is not null&&Environment.GetEnvironmentVariable("SHOP_TICKET_FILE_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);await File.WriteAllTextAsync(Path.Combine(dir,capture+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,capture+".meta.json"),System.Text.Json.JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,storeAndScannerAreTestCaptures=true,status=(int)response.StatusCode,method=response.RequestMessage!.Method.Method,path=response.RequestMessage.RequestUri!.PathAndQuery,cacheControl=response.Headers.CacheControl?.ToString()}));}return JsonNode.Parse(raw)!;}}
    private static async Task<JsonNode> Create(HttpClient c)=>await Json(await c.PostAsJsonAsync("/api/support/tickets/commands/"+Id(),new CreateTicketInput("تیکت ساختگی پیوست SQL","پیام اولیهٔ نمونه","fa")));
    private static string Value(JsonNode node,string field)=>node[field]!.GetValue<string>();
    [Fact]public async Task CustomerAndStaffFilesShareTheirReplyReceiptAndPrivateScopedDownloadWithoutLeakingKeys()
    {
        var store=new PrivateFileSqlTests.Store();using var factory=Factory(store,new());var person=await Customer(factory);using var customer=person.Client;using var staff=await Staff(factory);var created=await Create(customer);var ticket=Value(created["ticket"]!,"id");var command=Id();var path=$"/api/support/tickets/{ticket}/attachments/{command}";JsonNode uploaded;
        using(var form=Form(Value(created["ticket"]!,"version")))uploaded=await Json(await customer.PostAsync(path,form),"customer-upload");Assert.False(uploaded["replayed"]!.GetValue<bool>());Assert.Equal(2,uploaded["ticket"]!["messageCount"]!.GetValue<int>());
        using(var form=Form(Value(created["ticket"]!,"version"))){var repeated=await Json(await customer.PostAsync(path,form),"customer-replay");Assert.True(repeated["replayed"]!.GetValue<bool>());Assert.Equal(uploaded["messageId"]!.ToJsonString(),repeated["messageId"]!.ToJsonString());}
        await Json(await customer.GetAsync("/api/support/commands/"+command),"customer-receipt");var page=await Json(await customer.GetAsync($"/api/support/tickets/{ticket}/attachments"),"customer-files");var item=Assert.Single(page["items"]!.AsArray())!;Assert.Equal(Value(uploaded,"messageId"),Value(item,"messageId"));Assert.Equal("مدرک نمونه.pdf",Value(item["file"]!,"filename"));var fileId=Value(item,"id");var json=page.ToJsonString();Assert.DoesNotContain("protectedKey",json,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain("sha256",json,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain(person.Owner,json,StringComparison.OrdinalIgnoreCase);
        foreach(var (client,prefix)in new[]{(customer,"/api/support"),(staff,"/api/admin/support")}){using var response=await client.GetAsync($"{prefix}/tickets/{ticket}/attachments/{fileId}");Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Equal(Document(),await response.Content.ReadAsByteArrayAsync());Assert.Equal(fileId,response.Headers.GetValues("X-Sayman-Private-File").Single());Assert.Equal("attachment",response.Content.Headers.ContentDisposition!.DispositionType);Assert.Equal("مدرک نمونه.pdf",response.Content.Headers.ContentDisposition.FileNameStar);Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Contains("sandbox",response.Headers.GetValues("Content-Security-Policy").Single());}
        var staffCommand=Id();using(var form=Form(Value(uploaded["ticket"]!,"version"),"پاسخ همراه فایلِ نمونهٔ پشتیبان"))await Json(await staff.PostAsync($"/api/admin/support/tickets/{ticket}/attachments/{staffCommand}",form),"staff-upload");var final=await Json(await customer.GetAsync($"/api/support/tickets/{ticket}/attachments"),"files-after-staff");Assert.Equal(2,final["items"]!.AsArray().Count);Assert.Equal("support",Value(final["items"]![1]!,"author"));await Json(await staff.GetAsync("/api/admin/support/files/capabilities"),"capabilities");
        await using var scope=factory.Services.CreateAsyncScope();Assert.Equal(2,await scope.ServiceProvider.GetRequiredService<FilesDbContext>().Objects.CountAsync(x=>x.Kind=="support"&&x.ResourceId==ticket&&x.State=="Attached"));Assert.Single(await scope.ServiceProvider.GetRequiredService<NotificationsDbContext>().Inbox.Where(x=>x.TicketId==ticket).ToArrayAsync());Assert.Equal(2,store.Objects.Count);
    }
    [Fact]public async Task ForeignOwnersWrongRolesOriginsRangesAndChangedCommandInputNeverExposeOrRewriteAFile()
    {
        var store=new PrivateFileSqlTests.Store();var scanner=new PrivateFileSqlTests.Scan();using var factory=Factory(store,scanner);var person=await Customer(factory);using var customer=person.Client;var otherPerson=await Customer(factory);using var other=otherPerson.Client;using var sales=await Staff(factory,"SalesManager");var created=await Create(customer);var ticket=Value(created["ticket"]!,"id");var command=Id();var version=Value(created["ticket"]!,"version");using(var form=Form(version))await Json(await customer.PostAsync($"/api/support/tickets/{ticket}/attachments/{command}",form));var page=await Json(await customer.GetAsync($"/api/support/tickets/{ticket}/attachments"));var file=Value(page["items"]![0]!,"id");
        foreach(var path in new[]{$"/api/support/tickets/{ticket}/attachments",$"/api/support/tickets/{ticket}/attachments/{file}"})using(var forbidden=await other.GetAsync(path))Assert.Equal(HttpStatusCode.NotFound,forbidden.StatusCode);
        using(var form=Form(version)){using var denied=await other.PostAsync($"/api/support/tickets/{ticket}/attachments/{Id()}",form);Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);}using(var denied=await sales.GetAsync($"/api/admin/support/tickets/{ticket}/attachments/{file}"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        using(var form=Form(version,filename:"changed.pdf")){using var conflict=await customer.PostAsync($"/api/support/tickets/{ticket}/attachments/{command}",form);Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);}
        customer.DefaultRequestHeaders.Remove("Origin");customer.DefaultRequestHeaders.Add("Origin","https://wrong.example");using(var denied=await customer.GetAsync($"/api/support/tickets/{ticket}/attachments/{file}"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);customer.DefaultRequestHeaders.Remove("Origin");customer.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");customer.DefaultRequestHeaders.Range=new RangeHeaderValue(0,10);using(var denied=await customer.GetAsync($"/api/support/tickets/{ticket}/attachments/{file}"))Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);customer.DefaultRequestHeaders.Range=null;
        store.Objects[file][^1]^=1;using(var corrupt=await customer.GetAsync($"/api/support/tickets/{ticket}/attachments/{file}"))Assert.Equal(HttpStatusCode.ServiceUnavailable,corrupt.StatusCode);Assert.Equal(1,scanner.Calls);Assert.Single(store.Objects);
    }
    [Fact]public async Task UnknownObjectWriteIsRecoverableWithOriginalUploadWhileDisabledStorageDoesNotBreakTextReplies()
    {
        var store=new PrivateFileSqlTests.Store{LoseNextAcknowledgement=1};using var factory=Factory(store,new());var person=await Customer(factory);using var customer=person.Client;var created=await Create(customer);var ticket=Value(created["ticket"]!,"id");var command=Id();var version=Value(created["ticket"]!,"version");var path=$"/api/support/tickets/{ticket}/attachments/{command}";
        using(var form=Form(version)){using var lost=await customer.PostAsync(path,form);Assert.Equal(HttpStatusCode.ServiceUnavailable,lost.StatusCode);}using(var missing=await customer.GetAsync("/api/support/commands/"+command))Assert.Equal(HttpStatusCode.NotFound,missing.StatusCode);using(var changed=Form(version,"متن تغییرکرده با همان فرمان باید رد شود")){using var conflict=await customer.PostAsync(path,changed);Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);}using(var form=Form(version))await Json(await customer.PostAsync(path,form));Assert.Single(store.Objects);
        created=await Create(customer);ticket=Value(created["ticket"]!,"id");version=Value(created["ticket"]!,"version");store.Configured=false;var capability=await Json(await customer.GetAsync("/api/support/files/capabilities"));Assert.False(capability["configured"]!.GetValue<bool>());using(var form=Form(version)){using var disabled=await customer.PostAsync($"/api/support/tickets/{ticket}/attachments/{Id()}",form);Assert.Equal(HttpStatusCode.ServiceUnavailable,disabled.StatusCode);}await Json(await customer.PostAsJsonAsync($"/api/support/tickets/{ticket}/replies/{Id()}",new ReplyTicketInput(version,"پاسخ متنی در نبود ذخیره‌ساز فایل همچنان کار می‌کند.","fa")));Assert.Single(store.Objects);
    }
    [Fact]public async Task FailedStaffAuditRollsBackReplyAttachmentNotificationAndReceiptWhileKeepingPreparedCiphertextRecoverable()
    {
        var store=new PrivateFileSqlTests.Store();using var factory=Factory(store,new());var person=await Customer(factory);using var customer=person.Client;using var staff=await Staff(factory);var created=await Create(customer);var ticket=Value(created["ticket"]!,"id");var command=Id();var path=$"/api/admin/support/tickets/{ticket}/attachments/{command}";var version=Value(created["ticket"]!,"version");
        await using(var scope=factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<IdentityContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_PrivateAttachmentAuditFailure CHECK ([Action]<>'PRIVATE_FILE_ATTACH')");}
        try{using var form=Form(version);using var failed=await staff.PostAsync(path,form);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_PrivateAttachmentAuditFailure");}
        await using(var scope=factory.Services.CreateAsyncScope()){var support=scope.ServiceProvider.GetRequiredService<SupportDbContext>();Assert.Equal(1,await support.Messages.CountAsync(x=>x.TicketId==ticket));Assert.Empty(await support.Attachments.Where(x=>x.TicketId==ticket).ToArrayAsync());Assert.Empty(await support.Commands.Where(x=>x.CommandId==command).ToArrayAsync());Assert.Empty(await scope.ServiceProvider.GetRequiredService<NotificationsDbContext>().Inbox.Where(x=>x.TicketId==ticket).ToArrayAsync());Assert.Equal("Stored",(await scope.ServiceProvider.GetRequiredService<FilesDbContext>().Objects.SingleAsync(x=>x.ResourceId==ticket)).State);}
        using(var form=Form(version))await Json(await staff.PostAsync(path,form));using(var form=Form(version)){var replay=await Json(await staff.PostAsync(path,form));Assert.True(replay["replayed"]!.GetValue<bool>());}await using(var scope=factory.Services.CreateAsyncScope()){Assert.Equal(2,await scope.ServiceProvider.GetRequiredService<SupportDbContext>().Messages.CountAsync(x=>x.TicketId==ticket));Assert.Single(await scope.ServiceProvider.GetRequiredService<NotificationsDbContext>().Inbox.Where(x=>x.TicketId==ticket).ToArrayAsync());Assert.Equal(1,await scope.ServiceProvider.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Resource==path&&x.Action=="PRIVATE_FILE_ATTACH"));}Assert.Single(store.Objects);
    }
    [Fact]public async Task ConcurrentSameUploadAndExplicitRecoveryProduceOneReplyOneAttachmentAndOneAudit()
    {
        var store=new PrivateFileSqlTests.Store();using var factory=Factory(store,new());var person=await Customer(factory);using var customer=person.Client;var created=await Create(customer);var ticket=Value(created["ticket"]!,"id");var command=Id();var version=Value(created["ticket"]!,"version");var path=$"/api/support/tickets/{ticket}/attachments/{command}";
        async Task<HttpResponseMessage> Post(){using var form=Form(version);return await customer.PostAsync(path,form);}var responses=await Task.WhenAll(Post(),Post());var results=new List<JsonNode>();foreach(var response in responses){if(response.StatusCode==HttpStatusCode.ServiceUnavailable){response.Dispose();results.Add(await Json(await Post()));}else results.Add(await Json(response));}
        Assert.Single(results,x=>!x["replayed"]!.GetValue<bool>());Assert.Single(results,x=>x["replayed"]!.GetValue<bool>());Assert.Equal(results[0]["messageId"]!.ToJsonString(),results[1]["messageId"]!.ToJsonString());Assert.Single(store.Objects);
        await using var scope=factory.Services.CreateAsyncScope();var support=scope.ServiceProvider.GetRequiredService<SupportDbContext>();Assert.Single(await support.Attachments.Where(x=>x.TicketId==ticket).ToArrayAsync());Assert.Equal(2,await support.Messages.CountAsync(x=>x.TicketId==ticket));Assert.Equal(1,await support.Commands.CountAsync(x=>x.TicketId==ticket&&x.CommandId==command));Assert.Equal(1,await scope.ServiceProvider.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Resource==path&&x.Action=="PRIVATE_FILE_ATTACH"));
    }
    private sealed class DownloadWriteGate:IStartupFilter
    {
        private readonly TaskCompletionSource release=new(TaskCreationOptions.RunContinuationsAsynchronously);
        public readonly SemaphoreSlim Started=new(0);
        public void Release()=>release.TrySetResult();
        public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next)=>app=>{app.Use(async(http,run)=>{var original=http.Response.Body;http.Response.Body=new GateStream(original,http,this);try{await run();}finally{http.Response.Body=original;}});next(app);};
        private sealed class GateStream(Stream inner,HttpContext http,DownloadWriteGate gate):Stream
        {
            public override async ValueTask WriteAsync(ReadOnlyMemory<byte> buffer,CancellationToken ct=default){if(http.Request.Method=="GET"&&http.Request.Path.Value?.Contains("/attachments/",StringComparison.Ordinal)==true&&http.Response.ContentType=="application/pdf"){await http.Response.StartAsync(ct);gate.Started.Release();await gate.release.Task.WaitAsync(ct);}await inner.WriteAsync(buffer,ct);}
            public override Task WriteAsync(byte[] buffer,int offset,int count,CancellationToken ct)=>WriteAsync(buffer.AsMemory(offset,count),ct).AsTask();public override void Write(byte[] buffer,int offset,int count)=>inner.Write(buffer,offset,count);public override void Flush()=>inner.Flush();public override Task FlushAsync(CancellationToken ct)=>inner.FlushAsync(ct);public override bool CanRead=>false;public override bool CanSeek=>false;public override bool CanWrite=>true;public override long Length=>throw new NotSupportedException();public override long Position{get=>throw new NotSupportedException();set=>throw new NotSupportedException();}public override int Read(byte[] buffer,int offset,int count)=>throw new NotSupportedException();public override long Seek(long offset,SeekOrigin origin)=>throw new NotSupportedException();public override void SetLength(long value)=>throw new NotSupportedException();
        }
    }
    [Fact]public async Task DownloadSlotsRemainHeldThroughBodyWritingWithoutBlockingIndependentUploads()
    {
        var gate=new DownloadWriteGate();using var factory=Factory(new(),new(),gate);var person=await Customer(factory);using var customer=person.Client;var created=await Create(customer);var ticket=Value(created["ticket"]!,"id");JsonNode uploaded;using(var form=Form(Value(created["ticket"]!,"version")))uploaded=await Json(await customer.PostAsync($"/api/support/tickets/{ticket}/attachments/{Id()}",form));var page=await Json(await customer.GetAsync($"/api/support/tickets/{ticket}/attachments"));var id=Value(page["items"]![0]!,"id");var path=$"/api/support/tickets/{ticket}/attachments/{id}";
        using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(10));HttpResponseMessage? first=null,second=null,third=null;
        try{first=await customer.GetAsync(path,HttpCompletionOption.ResponseHeadersRead,deadline.Token);second=await customer.GetAsync(path,HttpCompletionOption.ResponseHeadersRead,deadline.Token);Assert.Equal(HttpStatusCode.OK,first.StatusCode);Assert.Equal(HttpStatusCode.OK,second.StatusCode);await gate.Started.WaitAsync(deadline.Token);await gate.Started.WaitAsync(deadline.Token);third=await customer.GetAsync(path,HttpCompletionOption.ResponseHeadersRead,deadline.Token);Assert.Equal(HttpStatusCode.ServiceUnavailable,third.StatusCode);
            using(var form=Form(Value(uploaded["ticket"]!,"version"),"آپلود مستقل هنگام بازبودن دو دانلود"))await Json(await customer.PostAsync($"/api/support/tickets/{ticket}/attachments/{Id()}",form,deadline.Token));gate.Release();Assert.Equal(Document(),await first.Content.ReadAsByteArrayAsync(deadline.Token));Assert.Equal(Document(),await second.Content.ReadAsByteArrayAsync(deadline.Token));using var recovered=await customer.GetAsync(path,deadline.Token);Assert.Equal(HttpStatusCode.OK,recovered.StatusCode);Assert.Equal(Document(),await recovered.Content.ReadAsByteArrayAsync(deadline.Token));
        }finally{gate.Release();first?.Dispose();second?.Dispose();third?.Dispose();}
    }
}
